6	import { WORK_PREFIX, labelNames } from './work-item.mjs';
7	
8	const project = (i) => ({
9	  number: i.number,
10	  title: i.title,
11	  body: i.body ?? '',
12	  state: i.state,
13	  labels: labelNames(i),
14	  created_at: i.created_at,
15	  closed_at: i.closed_at ?? null,
